    <script>function budgetForm(){return{eventId:@js(old('promotion_event_id', $budget->promotion_event_id)),eventDate:'',items:@js(old('items', $budget->items->map(fn($item)=>['title'=>$item->title,'quantity'=>$item->quantity,'unit_price'=>$item->unit_price,'note'=>$item->note])->values()->all()))||[{title:'',quantity:1,unit_price:0,note:''}],init(){if(this.eventId)this.loadEventDate()},blank(){return{title:'',quantity:1,unit_price:0,note:''}},remove(i){this.items.splice(i,1)},get total(){return this.items.reduce((sum,item)=>sum+(Number(item.quantity)||0)*(Number(item.unit_price)||0),0)},currency(value){return Number(value||0).toLocaleString('en-BD',{minimumFractionDigits:2})},async loadEventDate(){this.eventDate=this.eventId?(await(await fetch('/promotion/events/'+this.eventId+'/budget-info')).json()).date:''}}}</script>
